H.background();
// Elastic collision in 1D: both momentum AND kinetic energy are conserved.
// Two carts approach, collide at center, and rebound with new velocities given
// by the elastic-collision formulas. P sets the masses and incoming speeds.
const w = H.W, ht = H.H;
const m1 = Math.max(0.2, P.m1), m2 = Math.max(0.2, P.m2);
const u1 = P.v1, u2 = P.v2; // initial velocities (m/s)
// Post-collision velocities (1D elastic):
const M = m1 + m2;
const v1f = ((m1 - m2) * u1 + 2 * m2 * u2) / M;
const v2f = ((m2 - m1) * u2 + 2 * m1 * u1) / M;
// Track view in meters; carts meet at x = 0 at the collision instant tc.
const view = H.plot2d({ xMin: -10, xMax: 10, yMin: -3, yMax: 3, box: { x: 40, y: ht * 0.40, w: w - 80, h: ht * 0.34 } });
view.line(-10, -1.2, 10, -1.2, { color: H.colors.axis, width: 2 });
for (let gx = -10; gx <= 10; gx += 2) view.line(gx, -1.2, gx, -1.5, { color: H.colors.grid, width: 1 });
// Animation: loop period so carts come in, collide at tc, separate, then reset.
const period = 6.0, tc = 3.0;
const tt = t % period;
// Choose start offsets so both reach x=0 at t=tc (guard against zero speed).
const x1 = u1 * (tt - tc);
const x2 = u2 * (tt - tc);
// Use post-collision velocities after tc for visual rebound.
const X1 = tt < tc ? x1 : v1f * (tt - tc);
const X2 = tt < tc ? x2 : v2f * (tt - tc);
// Cart sizes scale with mass (radius in pixels).
const r1 = 12 + 10 * Math.sqrt(m1), r2 = 12 + 10 * Math.sqrt(m2);
const cx1 = view.X(H.clamp(X1, -9.5, 9.5)), cy = view.Y(-0.6);
const cx2 = view.X(H.clamp(X2, -9.5, 9.5));
H.circle(cx1, cy, r1 * 0.5, { fill: H.colors.accent, stroke: H.colors.bg, width: 2 });
H.circle(cx2, cy, r2 * 0.5, { fill: H.colors.accent2, stroke: H.colors.bg, width: 2 });
// Velocity arrows.
const vNow1 = tt < tc ? u1 : v1f, vNow2 = tt < tc ? u2 : v2f;
H.arrow(cx1, cy - r1 * 0.5 - 8, cx1 + vNow1 * 14, cy - r1 * 0.5 - 8, { color: H.colors.accent, width: 2.5 });
H.arrow(cx2, cy - r2 * 0.5 - 8, cx2 + vNow2 * 14, cy - r2 * 0.5 - 8, { color: H.colors.accent2, width: 2.5 });
// Conserved quantities.
const pBefore = m1 * u1 + m2 * u2;
const pAfter = m1 * v1f + m2 * v2f;
const keBefore = 0.5 * m1 * u1 * u1 + 0.5 * m2 * u2 * u2;
const keAfter = 0.5 * m1 * v1f * v1f + 0.5 * m2 * v2f * v2f;
H.text("Elastic collision: p and KE both conserved", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("v1' = ((m1−m2)v1 + 2 m2 v2)/(m1+m2)    v2' = ((m2−m1)v2 + 2 m1 v1)/(m1+m2)", 24, 52, { color: H.colors.sub, size: 12 });
H.text("before:  v1=" + u1.toFixed(1) + "  v2=" + u2.toFixed(1) + " m/s        after:  v1'=" + v1f.toFixed(2) + "  v2'=" + v2f.toFixed(2) + " m/s", 24, ht - 56, { color: H.colors.ink, size: 13 });
H.text("p = " + pBefore.toFixed(2) + " → " + pAfter.toFixed(2) + " kg·m/s     KE = " + keBefore.toFixed(2) + " → " + keAfter.toFixed(2) + " J", 24, ht - 34, { color: H.colors.good, size: 13 });
H.legend([{ label: "m1 = " + m1.toFixed(1) + " kg", color: H.colors.accent }, { label: "m2 = " + m2.toFixed(1) + " kg", color: H.colors.accent2 }], w - 160, 28);
